#
# GCU400-specific fix: torch_gcu has no Sparsegcu backend, so the original implementation raises
# NotImplementedError or core dumps when building sparse COO on device=gcu. Keep the Triton kernel
# computing values, then move indices/values back to CPU to build the COO sparse gradient (numeric semantics unchanged),
# and expose launch geometry / address computation as iterable TUNING parameters.
# Also fixes P17: without TORCH_GCU_ENABLE_INT64_AND_UINT64, int64 indices use compact 4B storage with 8B
# strides and are read incorrectly - offset2bag / bag_size(mean) are normalized via host-side `.to(torch.int32)`,
# so both env layouts are correct (as in embedding_sparse_backward).
import logging

import torch
import triton
import triton.language as tl

import flag_gems
from flag_gems.runtime import device
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

# --- TUNING PARAMS START ---
# Generated per round by the optimization driver script; only launch geometry and address computation change, not
# semantics.
SAMPLES_PER_PROG = 4
BLOCK_D_CAP = 256
D_THRESHOLD = 256
NUM_WARPS_SMALL = 4
NUM_WARPS_LARGE = 8
SPP_LARGE = 1
USE_INT64_OFFSET = 0
USE_CPU_SPARSE = 1
# --- TUNING PARAMS END ---


@libentry()
@triton.jit
def _embedding_bag_sparse_backward_kernel(
    grad_ptr,
    offset2bag_ptr,
    bag_size_ptr,
    per_sample_weights_ptr,
    values_ptr,
    num_valid_samples,
    EMBED_DIM,
    MODE: tl.constexpr,
    HAS_PSW: tl.constexpr,
    SAMPLES_PER_PROG: tl.constexpr,
    BLOCK_D: tl.constexpr,
    USE_INT64_OFFSET: tl.constexpr,
):
    """Each program handles a gradient slice of SAMPLES_PER_PROG consecutive valid samples."""
    pid = tl.program_id(0)
    pid_d = tl.program_id(1)

    offs_d = pid_d * BLOCK_D + tl.arange(0, BLOCK_D)
    mask_d = offs_d < EMBED_DIM

    for i in tl.static_range(SAMPLES_PER_PROG):
        pid_s = pid * SAMPLES_PER_PROG + i
        if pid_s < num_valid_samples:
            bag_idx = tl.load(offset2bag_ptr + pid_s).to(tl.int32)
            go_ptrs = grad_ptr + bag_idx * EMBED_DIM + offs_d
            go = tl.load(go_ptrs, mask=mask_d, other=0.0)

            if MODE == 1 or HAS_PSW:
                go = go.to(tl.float32)

            if MODE == 1:
                bag_size = tl.load(bag_size_ptr + bag_idx).to(tl.float32)
                bag_size = tl.where(bag_size == 0.0, 1.0, bag_size)
                go = go * (1.0 / bag_size)

            if HAS_PSW:
                pw = tl.load(per_sample_weights_ptr + pid_s).to(tl.float32)
                go = go * pw

            if USE_INT64_OFFSET:
                out_ptrs = values_ptr + pid_s.to(tl.int64) * EMBED_DIM + offs_d
            else:
                # nnz * EMBED_DIM is far below 2^31 for this operator's shapes,
                # so int32 offsets avoid the extra instructions of 64-bit address arithmetic on GCU.
                out_ptrs = values_ptr + pid_s * EMBED_DIM + offs_d
            tl.store(out_ptrs, go.to(values_ptr.dtype.element_ty), mask=mask_d)


def _sparse_output(valid_indices, values, num_weights, embedding_dim, device, dtype):
    """Build the COO sparse gradient; fall back to a CPU sparse tensor when GCU has no sparse backend."""
    if USE_CPU_SPARSE and device.type != "cpu":
        cpu_indices = valid_indices.detach().cpu().contiguous()
        cpu_values = values.detach().cpu().contiguous()
        return torch.sparse_coo_tensor(
            cpu_indices.unsqueeze(0),
            cpu_values,
            (num_weights, embedding_dim),
            device="cpu",
            dtype=dtype,
        )
    return torch.sparse_coo_tensor(
        valid_indices.unsqueeze(0),
        values,
        (num_weights, embedding_dim),
        device=device,
    )


def _embedding_bag_sparse_backward(
    grad: torch.Tensor,
    indices: torch.Tensor,
    offsets: torch.Tensor,
    offset2bag: torch.Tensor,
    bag_size: torch.Tensor,
    num_weights: int,
    scale_grad_by_freq: bool,
    mode: int,
    per_sample_weights: torch.Tensor = None,
    padding_idx: int = -1,
) -> torch.Tensor:
    """Compute the sparse (COO) gradient for embedding_bag backward (GCU400 tuned)."""
    logger.debug("GEMS_ENFLAME _EMBEDDING_BAG_SPARSE_BACKWARD")

    assert indices.dtype in (
        torch.int32,
        torch.int64,
    ), "Indices must be int32 or int64."
    assert (
        grad.device.type == flag_gems.device
        and indices.device.type == flag_gems.device
        and offset2bag.device.type == flag_gems.device
        and bag_size.device.type == flag_gems.device
        and grad.device == indices.device
    ), "All inputs must be on the same device."

    device = grad.device
    embedding_dim = grad.shape[1]

    # With padding_idx<0 reuse the input directly, avoiding a host-side boolean mask and an extra copy.
    has_padding = padding_idx is not None and padding_idx >= 0
    if has_padding:
        valid_mask = indices != padding_idx
        valid_indices = indices[valid_mask].to(torch.int64).contiguous()
        offset2bag_valid = offset2bag[valid_mask].contiguous()
        if per_sample_weights is not None:
            psw_valid = per_sample_weights.contiguous()[valid_mask]
        else:
            psw_valid = None
    else:
        valid_indices = (
            indices if indices.dtype == torch.int64 else indices.to(torch.int64)
        )
        offset2bag_valid = (
            offset2bag if offset2bag.is_contiguous() else offset2bag.contiguous()
        )
        psw_valid = (
            per_sample_weights.contiguous() if per_sample_weights is not None else None
        )

    # GCU's aten::_embedding_bag may return an empty offset2bag in SUM/MEAN, and ATen's sparse backward
    # also emits COO rows only for samples with a sample-to-bag mapping. Reduce the valid sample count to the
    # mapping table length and align the three arrays: this matches ATen semantics and avoids an async core dump
    # from the kernel reading a null pointer out of bounds.
    mapped_samples = min(valid_indices.numel(), offset2bag_valid.numel())
    if mapped_samples < valid_indices.numel():
        valid_indices = valid_indices[:mapped_samples].contiguous()
        offset2bag_valid = offset2bag_valid[:mapped_samples].contiguous()
        if psw_valid is not None:
            psw_valid = psw_valid[:mapped_samples].contiguous()

    nnz = mapped_samples
    grad_dtype = grad.dtype
    values = torch.empty((nnz, embedding_dim), device=device, dtype=grad_dtype)

    if nnz == 0:
        empty_indices = torch.empty(
            (1, 0), device="cpu" if USE_CPU_SPARSE else device, dtype=torch.int64
        )
        return _sparse_output(
            empty_indices[0],
            (
                values.detach().cpu()
                if USE_CPU_SPARSE and device.type != "cpu"
                else values
            ),
            num_weights,
            embedding_dim,
            device,
            grad_dtype,
        )

    psw_arg = psw_valid if psw_valid is not None else values
    has_psw = psw_valid is not None

    # P17 (following embedding_sparse_backward): without TORCH_GCU_ENABLE_INT64_AND_UINT64 torch_gcu silently
    # replaces int64 tensors with compact 4B storage; loading them with the claimed 8B dtype stride reads
    # interleaved garbage bag_idx/bag_size (measured wrong values and OOB aborts with env off in the mean case).
    # The bag domain is always < 2^31; host-side `.to(torch.int32)` normalization goes through torch_gcu's copy path
    # and reads the compact layout correctly, so both env layouts are deterministic (i32 safe range); the kernel also
    # casts to tl.int32.
    # Normalization is placed after the nnz==0 early return, so the empty-mapping degenerate path (benchmark case) has
    # zero extra cost.
    if offset2bag_valid.dtype == torch.int64:
        offset2bag_valid = offset2bag_valid.to(torch.int32)
    if mode == 1 and bag_size.dtype == torch.int64:
        bag_size = bag_size.to(torch.int32)

    if embedding_dim <= D_THRESHOLD:
        block_d = min(BLOCK_D_CAP, triton.next_power_of_2(max(embedding_dim, 1)))
        samples_per_prog = SAMPLES_PER_PROG
        num_warps = NUM_WARPS_SMALL if block_d < 256 else NUM_WARPS_LARGE
        grid = (triton.cdiv(nnz, samples_per_prog), 1)
    else:
        block_d = BLOCK_D_CAP if BLOCK_D_CAP >= 128 else 128
        samples_per_prog = SPP_LARGE
        num_warps = NUM_WARPS_SMALL
        grid = (nnz, triton.cdiv(embedding_dim, block_d))

    _embedding_bag_sparse_backward_kernel[grid](
        grad,
        offset2bag_valid,
        bag_size,
        psw_arg,
        values,
        nnz,
        embedding_dim,
        MODE=mode,
        HAS_PSW=has_psw,
        SAMPLES_PER_PROG=samples_per_prog,
        BLOCK_D=block_d,
        USE_INT64_OFFSET=USE_INT64_OFFSET,
        num_warps=num_warps,
    )

    return _sparse_output(
        valid_indices, values, num_weights, embedding_dim, device, grad_dtype
    )


# --- Dispatch wrapper: degenerate-mapping psw crash (aten reference leg) ------
# torch_gcu has no device kernel for aten::_embedding_bag_sparse_backward; the
# native composite runs the CPU implementation on GCU tensors. Its SUM-mode
# forward sibling (aten::_embedding_bag) falls back to the CPU ABI on GCU and
# returns an *empty* offset2bag, and the native backward then broadcasts the
# offset2bag-derived tensor against per_sample_weights and crashes
# ("The size of tensor a (0) must match the size of tensor b (N)") before the
# FlagGems candidate is ever reached. This registers a PrivateUse1 dispatch
# wrapper (upsample_nearest_exact3d_backward precedent):
#   * a deficient sample->bag mapping (offset2bag shorter than indices) with
#     per_sample_weights returns an empty COO gradient -- matching what the
#     native implementation itself returns for the same degenerate input
#     without per_sample_weights;
#   * while FlagGems is enabled (enable()/use_gems()) every call routes to
#     this module's implementation -- exactly what the registrar would have
#     installed (its re-registration is skipped with a warning, expected);
#   * otherwise calls forward to the captured native composite via call_boxed,
#     which bypasses the dispatcher: the reference leg stays the native
#     implementation and the forwarding cannot recurse.
_DISPATCH_FLAG = "_flaggems_gcu400_embedding_bag_sparse_backward_dispatch"
_DISPATCH_LIBRARY = None
_NATIVE_DEFAULT = None
_DEVICE_KEYSET = None


def _flaggems_enabled():
    # Lazy import: this module loads while ``flag_gems`` itself is still
    # initializing, but the wrapper below only ever runs afterwards.
    import flag_gems

    return getattr(flag_gems, "current_work_registrar", None) is not None


def _degenerate_mapping(indices, offset2bag, per_sample_weights):
    return (
        per_sample_weights is not None
        and isinstance(offset2bag, torch.Tensor)
        and isinstance(indices, torch.Tensor)
        and offset2bag.numel() < indices.numel()
    )


def _dispatch_default(
    grad,
    indices,
    offsets,
    offset2bag,
    bag_size,
    num_weights,
    scale_grad_by_freq,
    mode,
    per_sample_weights=None,
    padding_idx=-1,
):
    if _degenerate_mapping(indices, offset2bag, per_sample_weights):
        embedding_dim = grad.shape[-1] if grad.ndim >= 2 else 0
        return torch.sparse_coo_tensor(
            torch.empty((1, 0), dtype=torch.int64),
            torch.empty((0, embedding_dim), dtype=grad.dtype),
            (num_weights, embedding_dim),
        )
    if _flaggems_enabled():
        return _embedding_bag_sparse_backward(
            grad,
            indices,
            offsets,
            offset2bag,
            bag_size,
            num_weights,
            scale_grad_by_freq,
            mode,
            per_sample_weights,
            padding_idx,
        )
    return _NATIVE_DEFAULT.call_boxed(
        _DEVICE_KEYSET,
        grad,
        indices,
        offsets,
        offset2bag,
        bag_size,
        num_weights,
        scale_grad_by_freq,
        mode,
        per_sample_weights,
        padding_idx,
    )


def _install_dispatch_wrapper():
    global _DISPATCH_LIBRARY, _NATIVE_DEFAULT, _DEVICE_KEYSET
    if getattr(torch, _DISPATCH_FLAG, False):
        return
    if not hasattr(torch.library, "get_kernel"):
        return
    try:
        _NATIVE_DEFAULT = torch.library.get_kernel(
            torch.ops.aten._embedding_bag_sparse_backward.default,
            device.dispatch_key,
        )
        _DEVICE_KEYSET = torch._C.DispatchKeySet(
            getattr(torch._C.DispatchKey, device.dispatch_key)
        )
        library = torch.library.Library("aten", "IMPL")
        # The ".default" suffix is not a legal overload name, so the default
        # overload registers under the bare op name (matched by signature).
        library.impl(
            "_embedding_bag_sparse_backward",
            _dispatch_default,
            device.dispatch_key,
        )
    except RuntimeError as error:
        logger.warning(
            "_embedding_bag_sparse_backward dispatch wrapper skipped: %s", error
        )
        return
    _DISPATCH_LIBRARY = library
    setattr(torch, _DISPATCH_FLAG, True)


_install_dispatch_wrapper()
